xql_query:
// ============================================================
// Rule: CTX_Prevention Policy Changed
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Prevention Policy Changed.
// Severity: SEV_050_CRITICAL
// Category: TAMPERING
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1562 - Impair Defenses
// Technique: T1562.001 - Impair Defenses: Disable or Modify Tools

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: evitar perda de eventos por variações de caixa na descrição
config case_sensitive = false

// Fonte de dados: Management Audit Logs do Cortex
// O dataset 'management_auditing' registra ações administrativas realizadas no console,
// incluindo edições de políticas e regras de segurança por sistema operacional.
| dataset = management_auditing

// Filtro: monitora edição de regras de política (policy rules)
// - subtype = "Edit" indica modificação de um objeto existente
// - description contém o texto padrão que identifica regra de política para Windows/Linux/macOS
| filter subtype = "Edit"
| filter (
    description contains "Windows policy rule" or
    description contains "Linux policy rule" or
    description contains "MacOS policy rule"
)

// Seleção dos campos relevantes para auditoria e notificação do alerta
| fields
    description, // Detalhe da regra editada (geralmente inclui nome/objeto e contexto)
    user_name,   // Usuário administrador que realizou a edição
    subtype      // Subtipo do evento (Edit)
